20	// mirrorColumns is the human table/field view of a mirror: the scannable
21	// repo name, the clone URL you'd copy, and whether the upstream is
22	// private. The cluster is omitted — it's already embedded in the clone
23	// URL — and the wire model's internal ids are dropped entirely. The clone
24	// URL is synthesised from the mirror's coords (the form `git clone`
25	// accepts), since the list API doesn't return it.
26	var mirrorColumns = []string{"REPO", "CLONE URL", "PRIVATE"}
27	
28	func mirrorRow(m coreapi.Mirror) []string {
29		repo := m.Owner + "/" + m.Repo
30		cloneURL := fmt.Sprintf("entire://%s/gh/%s/%s", m.ClusterHost, m.Owner, m.Repo)
31		private := "no"
32		if m.IsPrivate.Or(false) {
33			private = "yes"
34		}
35		return []string{repo, cloneURL, private}
36	}
37	
38	// defaultClusterHost is the cluster the mirror commands target when the
39	// caller omits the <cluster-host> argument. A pragmatic single-region
40	// default for now — once multi-cluster selection lands this should come
41	// from config/context rather than a constant.
42	const defaultClusterHost = "aws-us-east-2.entire.io"
43	
44	// clusterArg returns the cluster host from the optional second positional
45	// (after <github-url>), or defaultClusterHost when it was omitted.
46	func clusterArg(args []string) string {
47		if len(args) > 1 {
48			return args[1]
49		}
50		return defaultClusterHost
51	}
52	
53	// clusterHostLabelRe matches one DNS label: alphanumeric, internal hyphens
54	// allowed, no leading/trailing hyphen.
55	var clusterHostLabelRe = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$`)
56	
57	// validateClusterHost rejects a cluster host that is anything other than a
58	// bare DNS name or IP with an optional :port. The host is concatenated as
59	// "https://"+host both into the smart-HTTP probe URL (waitForMirrorClone) and
60	// into the STS audience (auth.RepoScopedToken), so a value carrying URL
61	// metacharacters can redirect the request — and the repo-scoped basic-auth
62	// token it carries — somewhere other than the intended cluster. Classic case:
63	// `aws-us-east-2.entire.io@evil.com`, which Go's URL parser reads as
64	// host=evil.com with the real cluster demoted to userinfo, leaking the token
65	// to evil.com. We parse the host the same way the rest of the code does and
66	// require it to round-trip to a bare host with no userinfo, path, query, or
67	// fragment, then confirm the hostname is a valid IP or DNS name. This is
68	// cheap client-side defense-in-depth and doesn't depend on the server's STS
69	// invalid_target canonicalization catching the trick.
70	func validateClusterHost(host string) error {
71		if strings.TrimSpace(host) == "" {
72			return errors.New("cluster host is empty")
73		}
74		u, err := url.Parse("https://" + host)
75		if err != nil {
76			return fmt.Errorf("%q is not a valid host", host)
77		}
78		if u.User != nil || u.Path != "" || u.RawQuery != "" || u.Fragment != "" || u.Host != host {
79			return fmt.Errorf("%q must be a bare host[:port] (no scheme, userinfo, path, query, or fragment)", host)
80		}
81		hostname := u.Hostname()
82		if net.ParseIP(hostname) != nil {
83			return nil
84		}
85		for _, label := range strings.Split(hostname, ".") {
86			if !clusterHostLabelRe.MatchString(label) {
87				return fmt.Errorf("%q is not a valid DNS name or IP", host)
88			}
89		}
90		return nil
91	}
