93	// newRepoMirrorCmd is the `entire repo mirror` subtree: manage EntireDB
94	// GitHub-mirror placements on a cluster. Mirrors the standalone entiredb
95	// CLI's `entire repo mirror` surface for the server-side half (create /
96	// list / get / remove). The local-clone rewrite (`mirror use`) is not
97	// ported — it's a git-config + git-remote-entire concern outside the
98	// control-plane API.
99	func newRepoMirrorCmd() *cobra.Command {
100		cmd := &cobra.Command{
101			Use:   "mirror",
102			Short: "Manage GitHub-mirror placements on EntireDB clusters",
103		}
104		cmd.AddCommand(newRepoMirrorCreateCmd())
105		cmd.AddCommand(newRepoMirrorListCmd())
106		cmd.AddCommand(newRepoMirrorGetCmd())
107		cmd.AddCommand(newRepoMirrorRemoveCmd())
108		return cmd
109	}
110	
111	func newRepoMirrorCreateCmd() *cobra.Command {
112		var (
113			noWait      bool
114			waitTimeout time.Duration
115		)
116		cmd := &cobra.Command{
117			Use:   "create <github-url> [cluster-host]",
118			Short: "Register a GitHub mirror on a cluster",
119			Long: "Registers a mirror placement for a GitHub repo on the target " +
120				"cluster, then waits for the initial GitHub→EntireDB clone to " +
121				"finish so `git clone` works on return. Pass --no-wait to return " +
122				"as soon as the placement is registered. Idempotent on " +
123				"(upstream, cluster). The cluster-host defaults to " +
124				defaultClusterHost + " when omitted.",
125			Example: "  entire repo mirror create github.com/octocat/hello-world\n" +
126				"  entire repo mirror create github.com/octocat/hello-world eu-west-1.entire.io",
127			Args: cobra.RangeArgs(1, 2),
128			RunE: func(cmd *cobra.Command, args []string) error {
129				owner, repo, err := parseGitHubURL(args[0])
130				if err != nil {
131					cmd.SilenceUsage = true
132					return fmt.Errorf("invalid <github-url>: %w", err)
133				}
134				clusterHost := clusterArg(args)
135				if err := validateClusterHost(clusterHost); err != nil {
136					cmd.SilenceUsage = true
137					return fmt.Errorf("invalid [cluster-host]: %w", err)
138				}
139				return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
140					created, err := c.CreateMirror(ctx, &coreapi.CreateMirrorInputBody{
141						Provider:    coreapi.CreateMirrorInputBodyProviderGithub,
142						Owner:       owner,
143						Repo:        repo,
144						ClusterHost: clusterHost,
145					})
146					if err != nil {
147						return err
148					}
149					out := cmd.OutOrStdout()
150					repoSlug := "/gh/" + owner + "/" + repo
151					return finishMirrorCreate(out, cmd.ErrOrStderr(), created, noWait,
152						func() error {
153							if _, terr := auth.RepoScopedToken(ctx, clusterHost, repoSlug, "pull"); terr != nil {
154								return fmt.Errorf("probe mirror for suspension: %w", terr)
155							}
156							return nil
157						},
158						func() error {
159							return waitForMirrorClone(ctx, out, clusterHost, owner, repo, waitTimeout)
160						},
161					)
162				})
163			},
164		}
165		cmd.Flags().BoolVar(&noWait, "no-wait", false, "return once the placement is registered, without waiting for the initial clone")
166		cmd.Flags().DurationVar(&waitTimeout, "wait-timeout", 30*time.Minute, "how long to wait for the initial clone to finish")
167		return cmd
168	}
169	
170	// finishMirrorCreate prints the post-create status for `repo mirror create`
171	// and, unless noWait, makes sure the mirror is usable before returning.
172	//
173	// Empty upstream and suspended placement interact. An empty upstream has no
174	// clone to wait for, so the HEAD-poll loop is skipped — it could only spin to
175	// the timeout, since an empty repo never advertises a HEAD. But an *existing*
176	// placement can be suspended even when its upstream is empty, and the
177	// repo-scoped token exchange is the only signal that surfaces that; a *fresh*
178	// create can't be suspended (suspension follows upstream access loss), so it
179	// needs neither the probe nor the wait. Non-empty mirrors take the normal
180	// clone-wait path.
181	//
182	// probeSuspended mints a repo-scoped pull token and returns its error for
183	// explainSuspendedMirror to classify; waitClone runs the HEAD-poll loop. Both
184	// are injected so the branching is unit-testable without the auth and
185	// control-plane stack the production caller wires up.
186	func finishMirrorCreate(out, errW io.Writer, created *coreapi.CreatedMirror, noWait bool, probeSuspended, waitClone func() error) error {
187		if created.Created {
188			fmt.Fprintf(out, "Registered mirror %s\n", created.MirrorId)
189		} else {
190			fmt.Fprintf(out, "Mirror already exists (%s)\n", created.MirrorId)
191		}
192		fmt.Fprintf(out, "  %s\n", created.MirrorUrl)
193	
194		if created.Empty {
195			// An existing placement can sit behind a suspension even with an empty
196			// upstream, so probe the token exchange to surface it. A fresh create
197			// can't be suspended, so skip the probe there.
198			if !created.Created {
199				if err := probeSuspended(); err != nil {
200					if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
201						return serr
202					}
203					// A non-suspension probe error isn't fatal: the placement exists
204					// and the upstream is genuinely empty, so report that rather than
205					// failing the create on a transient token hiccup.
206				}
207			}
208			fmt.Fprintln(out, "Upstream has no commits yet — nothing to clone. The mirror will pick up refs once the upstream is pushed to.")
209			return nil
210		}
211	
212		if noWait {
213			fmt.Fprintf(out, "Initial clone may still be in progress; `git clone %s` will work once it completes.\n", created.MirrorUrl)
214			return nil
215		}
216		if err := waitClone(); err != nil {
217			if handled, serr := explainSuspendedMirror(errW, created.MirrorId, created.Created, err); handled {
218				return serr
219			}
220			return err
221		}
222		fmt.Fprintf(out, "\nClone it:\n  git clone %s\n", created.MirrorUrl)
223		return nil
224	}
