226	func newRepoMirrorListCmd() *cobra.Command {
227		var cluster, provider, owner string
228		cmd := &cobra.Command{
229			Use:   "list",
230			Short: "List mirrors you can see",
231			Args:  cobra.NoArgs,
232			RunE: func(cmd *cobra.Command, _ []string) error {
233				return runCoreList(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) ([]coreapi.Mirror, error) {
234					var params coreapi.ListMirrorsParams
235					if cluster != "" {
236						params.Cluster = coreapi.NewOptString(cluster)
237					}
238					if provider != "" {
239						params.Provider = coreapi.NewOptString(provider)
240					}
241					if owner != "" {
242						params.Owner = coreapi.NewOptString(owner)
243					}
244					out, err := c.ListMirrors(ctx, params)
245					if err != nil {
246						return nil, err
247					}
248					return out.Mirrors, nil
249				})
250			},
251		}
252		cmd.Flags().StringVar(&cluster, "cluster", "", "filter by cluster public host")
253		cmd.Flags().StringVar(&provider, "provider", "", "filter by upstream provider (e.g. github)")
254		cmd.Flags().StringVar(&owner, "owner", "", "filter by upstream owner login")
255		return cmd
256	}
257	
258	func newRepoMirrorGetCmd() *cobra.Command {
259		return &cobra.Command{
260			Use:   "get <mirror-id>",
261			Short: "Show a mirror by ULID",
262			Args:  cobra.ExactArgs(1),
263			RunE: func(cmd *cobra.Command, args []string) error {
264				return runCoreObject(cmd, mirrorColumns, mirrorRow, func(ctx context.Context, c *coreapi.Client) (*coreapi.Mirror, error) {
265					sc, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: args[0]})
266					if err != nil {
267						return nil, err
268					}
269					return sc, nil
270				})
271			},
272		}
273	}
274	
275	func newRepoMirrorRemoveCmd() *cobra.Command {
276		return &cobra.Command{
277			Use:   "remove <github-url> [cluster-host]",
278			Short: "Un-register a GitHub mirror from a cluster",
279			Long: "Removes a mirror placement for a GitHub repo from the target " +
280				"cluster. Other clusters' placements of the same upstream are " +
281				"unaffected. The cluster-host defaults to " + defaultClusterHost +
282				" when omitted.",
283			Example: "  entire repo mirror remove github.com/octocat/hello-world",
284			Args:    cobra.RangeArgs(1, 2),
285			RunE: func(cmd *cobra.Command, args []string) error {
286				owner, repo, err := parseGitHubURL(args[0])
287				if err != nil {
288					cmd.SilenceUsage = true
289					return fmt.Errorf("invalid <github-url>: %w", err)
290				}
291				clusterHost := clusterArg(args)
292				if err := validateClusterHost(clusterHost); err != nil {
293					cmd.SilenceUsage = true
294					return fmt.Errorf("invalid [cluster-host]: %w", err)
295				}
296				return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
297					// Delete by upstream coords in one call. A 404 is a real
298					// error here, not idempotent success: the server only
299					// answers 204 when it actually removed a placement, so a
300					// 404 ("no such mirror / not visible / different cluster")
301					// surfaces verbatim via renderCoreError rather than being
302					// reported as a successful removal.
303					if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
304						Provider:    coreapi.DeleteMirrorProviderGithub,
305						Owner:       owner,
306						Repo:        repo,
307						ClusterHost: clusterHost,
308					}); err != nil {
309						return err
310					}
311					cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
312					return nil
313				})
314			},
315		}
316	}
