}

// requireOrgAdmin runs the live GitHub org-admin check with the caller's
// personal token (COR-431): minting the org-wide link on first mirror requires
// org-admin, even though repo-admin is enough to mirror into a linked org.
func (s *Server) requireOrgAdmin(ctx context.Context, claims *authn.Claims, orgLogin string) *MirrorOpError {
	if s.githubAdminChecker == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "github admin check not configured"}
	}
	isAdmin, err := s.githubAdminChecker.IsOrgAdmin(ctx, claims.AccountID, orgLogin)
	return s.mirrorAdminCheckError(ctx, isAdmin, err, "you must be an admin of this GitHub organization to mirror its first repo (this links the org)")
}

// mirrorAdminCheckError maps a live IsRepoAdmin/IsOrgAdmin result to a
// MirrorOpError, sharing coreapi's org-link endpoint mapping: a missing/stale
// GitHub link is a 401 relink prompt, a GitHub transport error is a 502, a
// clean non-admin is a 403 with notAdminMsg. Returns nil when the caller is an
// admin.
func (s *Server) mirrorAdminCheckError(ctx context.Context, isAdmin bool, err error, notAdminMsg string) *MirrorOpError {
	if err != nil {
		if githubperms.IsGitHubLinkRequired(err) {
			return &MirrorOpError{Status: http.StatusUnauthorized, Message: "(re)link your GitHub account to continue"}
		}
		var httpErr *githubapi.HTTPError
		if errors.As(err, &httpErr) {
			return &MirrorOpError{Status: http.StatusBadGateway, Message: "github admin check failed: " + httpErr.Error()}
		}
		slogutil.Error(ctx, "mirror create: github admin check failed", slog.Any("error", err))
		return &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("github admin check: %v", err)}
	}
	if !isAdmin {
		return &MirrorOpError{Status: http.StatusForbidden, Message: notAdminMsg}
	}
	return nil
}

package githubperms

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"entire.io/core/githubperms/githubapi"
	"entire.io/core/githubtokens"
	"entire.io/core/identity"
	"entire.io/core/model"
)

// ErrGitHubLinkRequired signals that a live admin check could not run
// because the caller's GitHub link is missing, never established, or no
// longer refreshable. It is a caller-actionable auth state, not a
// server fault: the API layer surfaces it as "(re)link your GitHub
// account". The three upstream conditions collapse into it so callers
// get one stable signal regardless of which tripped:
//   - no `github` handle on the account (identity.ErrNotFound)
//   - no stored OAuth credential (githubtokens.ErrNotLinked)
//   - a refresh token GitHub rejected (githubtokens.ErrRefreshRevoked)
var ErrGitHubLinkRequired = errors.New("github account link required")

// GitHub's GET /orgs/{org}/memberships/{username} reports membership as
// a (state, role) pair. "Currently an admin" is the strict reading:
// an accepted membership (not a pending invite) whose role is admin
// (org owner). A pending admin invite is not yet effective access.
const (
	orgMembershipActive = "active"
	orgRoleAdmin        = "admin"
)

// HandleResolver resolves an Entire account to its linked GitHub login.
// Both endpoints the checker hits are keyed on login, not on the numeric
