// effective access.
//
// Returns ErrGitHubLinkRequired when the caller hasn't (re)linked
// GitHub. Other GitHub failures (e.g. an SSO-enforcing org's 403) carry
// through as *githubapi.HTTPError so the API layer can distinguish a
// transient/operator condition from a clean not-admin verdict.
func (a *AdminChecker) IsOrgAdmin(ctx context.Context, account model.AccountID, org string) (bool, error) {
	login, token, err := a.resolve(ctx, account)
	if err != nil {
		return false, err
	}
	m, err := a.api.GetOrgMembership(ctx, token, org, login)
	if err != nil {
		if errors.Is(err, githubapi.ErrNotFound) {
			return false, nil
		}
		return false, fmt.Errorf("get org membership %s/%s: %w", org, login, err)
	}
	return m.State == orgMembershipActive && m.Role == orgRoleAdmin, nil
}

// IsRepoAdmin reports whether the account's linked GitHub user currently
// holds admin permission on owner/repo, checked live against
// GET /repos/{owner}/{repo}/collaborators/{username}/permission and
// flattened through the shared permission mapping. Non-collaborators (and
// collaborators with a sub-admin effective permission) return
// (false, nil).
//
// A personal-account owner is admin of their own repo but is NOT returned
// by the collaborators endpoint — GitHub doesn't model the owner as a
// collaborator on their own repo, so the call 404s, which would otherwise
// read as not-admin (the same gap [PersonalOwnerEdge] patches on the
// mirror path). GitHub logins and org names share one global, unique
// namespace, so owner == the caller's login can only mean the caller
// personally owns the repo; we short-circuit to admin before the call.
//
// Returns ErrGitHubLinkRequired when the caller hasn't (re)linked
// GitHub; other GitHub failures carry through as *githubapi.HTTPError.
func (a *AdminChecker) IsRepoAdmin(ctx context.Context, account model.AccountID, owner, repo string) (bool, error) {
	login, token, err := a.resolve(ctx, account)
	if err != nil {
		return false, err
	}
	// resolve already proved the caller holds a live, refreshable GitHub
	// credential; for a repo in their own namespace that ownership is the
	// whole verdict — see the doc comment for why owner == login implies it.
	if strings.EqualFold(login, owner) {
		return true, nil
	}
	perm, err := a.api.GetCollaboratorPermission(ctx, token, owner, repo, login)
	if err != nil {
		if errors.Is(err, githubapi.ErrNotFound) {
			return false, nil
		}
		return false, fmt.Errorf("get collaborator permission %s/%s/%s: %w", owner, repo, login, err)
	}
	return MapCollaboratorPermissionResponse(perm).Allows(PermissionAdmin), nil
}

// resolve turns an Entire account into the (login, fresh personal token)
// pair both checks need. The three "caller hasn't (re)linked GitHub"
// conditions collapse to ErrGitHubLinkRequired; any other error from the
// handle lookup or token refresh passes through unwrapped so genuine
// faults (a non-numeric handle, a KMS/DB outage) aren't misreported as a
// link problem.
func (a *AdminChecker) resolve(ctx context.Context, account model.AccountID) (login, token string, err error) {
	_, login, err = a.handles.GitHubHandleForAccount(ctx, account)
	if err != nil {
		if errors.Is(err, identity.ErrNotFound) {
			return "", "", fmt.Errorf("account %s has no linked github handle: %w", account, ErrGitHubLinkRequired)
		}
		return "", "", fmt.Errorf("resolve github handle for %s: %w", account, err)
	}
	token, _, err = a.tokens.GetAccessToken(ctx, account)
	if err != nil {
		if errors.Is(err, githubtokens.ErrNotLinked) || errors.Is(err, githubtokens.ErrRefreshRevoked) {
			return "", "", fmt.Errorf("account %s github token unusable: %w", account, ErrGitHubLinkRequired)
		}
		return "", "", fmt.Errorf("get github access token for %s: %w", account, err)
	}
	return login, token, nil
}

// IsGitHubLinkRequired reports whether err signals "the caller must
// (re)link their GitHub account" — sugar so API handlers don't import
// the sentinel directly.
func IsGitHubLinkRequired(err error) bool { return errors.Is(err, ErrGitHubLinkRequired) }

