	case githubperms.AccountTypeUser:
		// Only the Entire user who IS the GitHub owner may mirror a user-owned
		// repo; the project is owned by that account (the caller).
		if callerGitHubUserID != acct.AccountID {
			return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusForbidden, Message: "only the GitHub owner of this repository may mirror it"}
		}
		return mirrorProjectOwner{Type: "account", ID: model.ID(claims.AccountID.String())}, nil

	case githubperms.AccountTypeOrganization:
		if oerr := s.requireRepoAdmin(ctx, claims, owner, repo); oerr != nil {
			return mirrorProjectOwner{}, oerr
		}
		return s.resolveOrCreateLinkedOrgForCaller(ctx, claims, acct)

	default:
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusBadRequest, Message: fmt.Sprintf("unsupported GitHub account type %q", acct.AccountType)}
	}
}

// resolveAdminMirrorOwner resolves the parent-project owner for the operator
// (platform-admin) create path. No caller gate — operators may mirror repos
// they don't own — so a user-owned upstream is owned by the upstream owner's
// Entire account, resolved by GitHub user id. A missing link (org) or a GitHub
// user with no Entire account (user) strands creation.
func (s *Server) resolveAdminMirrorOwner(ctx context.Context, owner string) (mirrorProjectOwner, *MirrorOpError) {
	acct, oerr := s.resolveMirrorUpstreamAccount(ctx, owner)
	if oerr != nil {
		return mirrorProjectOwner{}, oerr
	}

	switch acct.AccountType {
	case githubperms.AccountTypeUser:
		if s.identity == nil {
			return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "identity service not configured"}
		}
		ownerAcct, _, err := s.identity.ResolveHandleByProviderID(ctx, "github", strconv.FormatInt(acct.AccountID, 10))
		if err != nil {
			if errors.Is(err, identity.ErrNotFound) {
				return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusPreconditionFailed, Message: "the upstream GitHub user has no linked Entire account; cannot own the mirror"}
			}
			slogutil.Error(ctx, "admin mirror create: resolve owner account failed", slog.Any("error", err))
			return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("resolve owner account: %v", err)}
		}
		return mirrorProjectOwner{Type: "account", ID: model.ID(ownerAcct.ID.String())}, nil

	case githubperms.AccountTypeOrganization:
		return s.createOrFindLinkedOrgForAdmin(ctx, acct)

	default:
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusBadRequest, Message: fmt.Sprintf("unsupported GitHub account type %q", acct.AccountType)}
	}
}

// resolveOrCreateLinkedOrgForCaller resolves the org-owned upstream's COR-432
// linked org, creating it on first mirror when missing. Repo-admin (checked by
// the caller) is enough to mirror into an already-linked org, but minting the
// org-wide link requires a live org-admin check (the caller's personal token),
// matching the COR-432 link endpoint's gate.
func (s *Server) resolveOrCreateLinkedOrgForCaller(ctx context.Context, claims *authn.Claims, acct githubperms.InstallationAccount) (mirrorProjectOwner, *MirrorOpError) {
	if s.resource == nil {
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "resource service not configured"}
	}
	org, err := s.resource.GetGitHubLinkedOrg(ctx, acct.AccountID, acct.AccountLogin)
	if errors.Is(err, resource.ErrNotFound) {
		if oerr := s.requireOrgAdmin(ctx, claims, acct.AccountLogin); oerr != nil {
			return mirrorProjectOwner{}, oerr
		}
		org, _, err = s.resource.CreateOrFindGitHubLinkedOrg(ctx, acct.AccountID, acct.AccountLogin, s.jurisdiction)
	}
	if err != nil {
		slogutil.Error(ctx, "mirror create: resolve-or-create linked org failed", slog.Any("error", err))
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("resolve linked org: %v", err)}
	}
	return mirrorProjectOwner{Type: "org", ID: model.ID(org.ID.String())}, nil
}

// createOrFindLinkedOrgForAdmin resolves (creating if missing) the linked org on
// the operator path. No GitHub admin check: platform-admin authority already
// gates the admin endpoint, and there's no caller token to run IsOrgAdmin with.
func (s *Server) createOrFindLinkedOrgForAdmin(ctx context.Context, acct githubperms.InstallationAccount) (mirrorProjectOwner, *MirrorOpError) {
	if s.resource == nil {
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "resource service not configured"}
	}
	org, _, err := s.resource.CreateOrFindGitHubLinkedOrg(ctx, acct.AccountID, acct.AccountLogin, s.jurisdiction)
	if err != nil {
		slogutil.Error(ctx, "admin mirror create: create-or-find linked org failed", slog.Any("error", err))
		return mirrorProjectOwner{}, &MirrorOpError{Status: http.StatusInternalServerError, Message: fmt.Sprintf("resolve linked org: %v", err)}
	}
	return mirrorProjectOwner{Type: "org", ID: model.ID(org.ID.String())}, nil
}

// requireRepoAdmin runs the live GitHub repo-admin check with the caller's
// personal token (COR-431): a non-admin caller may not mirror the repo.
func (s *Server) requireRepoAdmin(ctx context.Context, claims *authn.Claims, owner, repo string) *MirrorOpError {
	if s.githubAdminChecker == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "github admin check not configured"}
	}
	isAdmin, err := s.githubAdminChecker.IsRepoAdmin(ctx, claims.AccountID, owner, repo)
	return s.mirrorAdminCheckError(ctx, isAdmin, err, "you must be an admin of this repository on GitHub to mirror it")
}

// requireOrgAdmin runs the live GitHub org-admin check with the caller's
// personal token (COR-431): minting the org-wide link on first mirror requires
// org-admin, even though repo-admin is enough to mirror into a linked org.
func (s *Server) requireOrgAdmin(ctx context.Context, claims *authn.Claims, orgLogin string) *MirrorOpError {
	if s.githubAdminChecker == nil {
		return &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "github admin check not configured"}
	}
	isAdmin, err := s.githubAdminChecker.IsOrgAdmin(ctx, claims.AccountID, orgLogin)
	return s.mirrorAdminCheckError(ctx, isAdmin, err, "you must be an admin of this GitHub organization to mirror its first repo (this links the org)")
}

// mirrorAdminCheckError maps a live IsRepoAdmin/IsOrgAdmin result to a
// MirrorOpError, sharing coreapi's org-link endpoint mapping: a missing/stale
